#include <xrt/xrt_bo.h>
#include <xrt/xrt_device.h>
#include <xrt/xrt_kernel.h>
#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <optional>
#include <stdexcept>
#include <string>
#include <vector>

// Generated by invoke.py
#include "generate_txn.h"

// Tile sizes must match invoke.py.
static const int32_t kGroups = 8;
static const int32_t kComputesPerGroup = 4;
static const int32_t kL2Inputs = 64 * kComputesPerGroup;
static const int32_t kL3Inputs = kL2Inputs * kGroups;
static const int32_t kL3Outputs = 64 * kComputesPerGroup * kGroups;  // 2048

// Kernel launch parameters: arg 0 is the runtime opcode (see NPU docs) and
// every run waits at most this long before timing out.
static const uint32_t kRunOpcode = 3;
static const int kRunTimeoutMs = 5000;

// generate_txn_main_sequence returns std::optional<std::vector<uint32_t>>; it
// is empty when the runtime sequence can not be generated (e.g. the folded
// instruction stream overflows its internal size fields). Dereferencing an
// empty optional is undefined behaviour, so check it before use.
static void require_insts(const std::optional<std::vector<uint32_t>>& insts,
                          int32_t input_steps,
                          int32_t output_steps) {
  if (!insts.has_value()) {
    throw std::runtime_error("generate_txn_main_sequence failed for (" +
                             std::to_string(input_steps) + ", " +
                             std::to_string(output_steps) + ")");
  }
}

struct Bos {
  xrt::bo instr, config, inputs, outputs;
};

static Bos make_bos(xrt::device& device,
                    xrt::kernel& kernel,
                    size_t instr_bytes,
                    size_t config_bytes,
                    size_t inputs_bytes,
                    size_t outputs_bytes) {
  Bos b;
  b.instr = xrt::bo(device, instr_bytes, xrt::bo::flags::cacheable,
                    kernel.group_id(1));
  b.config = xrt::bo(device, config_bytes, xrt::bo::flags::host_only,
                     kernel.group_id(3));
  b.inputs = xrt::bo(device, inputs_bytes, xrt::bo::flags::host_only,
                     kernel.group_id(4));
  b.outputs = xrt::bo(device, outputs_bytes, xrt::bo::flags::host_only,
                      kernel.group_id(5));
  return b;
}

static void write_insts(xrt::bo& instr_bo, const std::vector<uint32_t>& insts) {
  size_t nbytes = insts.size() * sizeof(uint32_t);
  instr_bo.write(insts.data(), nbytes, 0);
  instr_bo.sync(XCL_BO_SYNC_BO_TO_DEVICE);
}

static void set_config(xrt::bo& config_bo,
                       int32_t input_steps,
                       int32_t output_steps) {
  auto buf = config_bo.map<int32_t*>();
  for (int32_t i = 0; i < kComputesPerGroup; i++) {
    buf[64 * i + 0] = input_steps;
    buf[64 * i + 1] = output_steps;
  }
  config_bo.sync(XCL_BO_SYNC_BO_TO_DEVICE);
}

static void fill_inputs(xrt::bo& inputs_bo, int32_t inputs_len) {
  auto buf = inputs_bo.map<int32_t*>();
  for (int32_t i = 0; i < inputs_len; i++) {
    buf[i] = i;
  }
  inputs_bo.sync(XCL_BO_SYNC_BO_TO_DEVICE);
}

// Generate the instruction stream and load the buffers/config for a given
// (input_steps, output_steps) shape, so every mode sets up a workload the same
// way.
struct Prepared {
  Bos bos;
  std::vector<uint32_t> insts;
};

static Prepared prepare(xrt::device& device,
                        xrt::kernel& kernel,
                        int32_t input_steps,
                        int32_t output_steps) {
  auto insts = generate_txn_main_sequence(input_steps, output_steps);
  require_insts(insts, input_steps, output_steps);

  Prepared p;
  p.bos = make_bos(device, kernel, insts->size() * sizeof(uint32_t),
                   (size_t)kL2Inputs * sizeof(int32_t),
                   (size_t)kL3Inputs * input_steps * sizeof(int32_t),
                   (size_t)kL3Outputs * output_steps * sizeof(int32_t));
  write_insts(p.bos.instr, *insts);
  set_config(p.bos.config, input_steps, output_steps);
  fill_inputs(p.bos.inputs, kL3Inputs * input_steps);
  p.insts = std::move(*insts);
  return p;
}

// Bind the six kernel arguments shared by every run object.
static void bind_args(xrt::run& run, const Bos& b, size_t insts_n) {
  run.set_arg(0, kRunOpcode);
  run.set_arg(1, b.instr);
  run.set_arg(2, (uint32_t)insts_n);
  run.set_arg(3, b.config);
  run.set_arg(4, b.inputs);
  run.set_arg(5, b.outputs);
}

static void issue_run(xrt::kernel& kernel, Bos& b, size_t insts_n) {
  auto run = xrt::run(kernel);
  bind_args(run, b, insts_n);
  run.start();
  run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
}

// Time just the dispatch + wait window (run creation, arg binding, start and
// wait) with no host<->device transfers. This brackets the same span as the
// Python benchmark's "npu" figure, which is a host-clock delta around dispatch
// + wait and excludes load, transfers and Python overhead (see npu-vs-e2e.md).
static double timed_run(xrt::kernel& kernel, Bos& b, size_t insts_n) {
  auto t0 = std::chrono::steady_clock::now();
  issue_run(kernel, b, insts_n);
  auto t1 = std::chrono::steady_clock::now();
  return std::chrono::duration<double, std::micro>(t1 - t0).count();
}

// A pre-configured run object plus the buffers its arguments point at. The run
// is built once (args bound, instruction stream and config loaded) so it can be
// started repeatedly without any per-call setup.
struct RunCtx {
  Bos bos;
  xrt::run run;
  size_t insts_n;
};

static RunCtx make_run(xrt::device& device,
                       xrt::kernel& kernel,
                       int32_t input_steps,
                       int32_t output_steps) {
  Prepared p = prepare(device, kernel, input_steps, output_steps);

  RunCtx ctx;
  ctx.bos = std::move(p.bos);
  ctx.insts_n = p.insts.size();
  ctx.run = xrt::run(kernel);
  bind_args(ctx.run, ctx.bos, ctx.insts_n);
  return ctx;
}

// Time a start + wait on an already-configured run object.
static double timed_start(xrt::run& run) {
  auto startTime = std::chrono::steady_clock::now();
  run.start();
  run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
  auto endTime = std::chrono::steady_clock::now();
  return std::chrono::duration<double, std::micro>(endTime - startTime).count();
}

// Running min/max/total accumulator for a timed loop.
struct Stats {
  double total = 0, mn = 1e30, mx = 0;

  void add(double t) {
    total += t;
    mn = std::min(mn, t);
    mx = std::max(mx, t);
  }

  void report(const char* label, int32_t n) const {
    printf("  %-20s %7.1f    (%6.1f-%6.1f)\n", label, total / n, mn, mx);
  }
};

static void report_failure(const char* label) {
  printf("  %-20s failed verification\n", label);
}

static bool verify(xrt::bo& bo, int32_t input_steps, int32_t output_steps) {
  bo.sync(XCL_BO_SYNC_BO_FROM_DEVICE);
  auto out = bo.map<const int32_t*>();

  // The kernel zeroes each output buffer, then for every input step adds the
  // input buffer element-wise. fill_inputs writes buf[i] = i, so the value at
  // an input position is its absolute index. The strided fill feeds worker
  // (g, worker_idx) the value at index
  //   l2_inputs_len * g + l1_inputs_len * worker_idx + compute_idx
  //     + input_step * l3_inputs_len
  // and the join/drain places its compute_idx result at output position
  //   output_steps * l3_outputs_len + l2_outputs_len * g
  //     + l1_outputs_len * worker_idx + compute_idx.
  // This mirrors the reference model in invoke.py (_run).

  const int32_t kL1Inputs = 64;
  const int32_t kL1Outputs = 64;
  const int32_t kL2Outputs = kL1Outputs * kComputesPerGroup;  // 256

  int32_t outputs_len = kL3Outputs * output_steps;
  for (int32_t idx = 0; idx < outputs_len; idx++) {
    int32_t rem = idx % kL3Outputs;
    int32_t g = rem / kL2Outputs;
    int32_t rem2 = rem % kL2Outputs;
    int32_t worker_idx = rem2 / kL1Outputs;
    int32_t compute_idx = rem2 % kL1Outputs;

    // base = index of compute_idx for worker (g, worker_idx) within one input
    // step.
    int32_t base = kL2Inputs * g + kL1Inputs * worker_idx + compute_idx;
    // expected = sum over s in [0, input_steps) of (base + s * l3_inputs_len).
    int32_t expected =
        input_steps * base + kL3Inputs * (input_steps * (input_steps - 1) / 2);

    if (out[idx] != expected) {
      return false;
    }
  }
  return true;
}

// Each benchmark mode is a self-contained function taking the device, kernel,
// the (input_steps, output_steps) shapes it benchmarks, call count and warmup
// count; main below only parses argv, defines the shapes and dispatches to one
// of them. Every mode runs (and verifies the outputs of) one warmup
// unconditionally, so a failure is reported even when num_warmups is zero.

// Repeatedly launch a single workload, creating a new xrt::run object each
// time.
static int mode_repeat(xrt::device& device,
                       xrt::kernel& kernel,
                       const char* label,
                       int32_t input_steps,
                       int32_t output_steps,
                       int32_t num_calls,
                       int32_t num_warmups) {
  Prepared p = prepare(device, kernel, input_steps, output_steps);

  // Verify the first warmup run.
  timed_run(kernel, p.bos, p.insts.size());
  if (!verify(p.bos.outputs, input_steps, output_steps)) {
    report_failure(label);
    return 0;
  }
  for (int32_t w = 1; w < num_warmups; w++) {
    timed_run(kernel, p.bos, p.insts.size());
  }

  // Collect stats for the benchmark runs.
  Stats s;
  for (int32_t i = 0; i < num_calls; i++) {
    s.add(timed_run(kernel, p.bos, p.insts.size()));
  }
  s.report(label, num_calls);
  return 0;
}

// Launch alternating workloads through a single xrt::run object.
static int mode_alternate(xrt::device& device,
                          xrt::kernel& kernel,
                          int32_t a_input_steps,
                          int32_t a_output_steps,
                          int32_t b_input_steps,
                          int32_t b_output_steps,
                          int32_t num_calls,
                          int32_t num_warmups) {
  auto insts_a = generate_txn_main_sequence(a_input_steps, a_output_steps);
  auto insts_b = generate_txn_main_sequence(b_input_steps, b_output_steps);
  require_insts(insts_a, a_input_steps, a_output_steps);
  require_insts(insts_b, b_input_steps, b_output_steps);
  int32_t max_input_steps = std::max(a_input_steps, b_input_steps);
  int32_t max_output_steps = std::max(a_output_steps, b_output_steps);
  Bos b =
      make_bos(device, kernel,
               std::max(insts_a->size(), insts_b->size()) * sizeof(uint32_t),
               (size_t)kL2Inputs * sizeof(int32_t),
               (size_t)kL3Inputs * max_input_steps * sizeof(int32_t),
               (size_t)kL3Outputs * max_output_steps * sizeof(int32_t));
  fill_inputs(b.inputs, kL3Inputs * max_input_steps);

  // Verify the first warmup run. Each shape writes the shared output buffer,
  // so check it after each run rather than after both.
  write_insts(b.instr, *insts_a);
  set_config(b.config, a_input_steps, a_output_steps);
  issue_run(kernel, b, insts_a->size());
  if (!verify(b.outputs, a_input_steps, a_output_steps)) {
    report_failure("alternate A");
    return 0;
  }

  write_insts(b.instr, *insts_b);
  set_config(b.config, b_input_steps, b_output_steps);
  issue_run(kernel, b, insts_b->size());
  if (!verify(b.outputs, b_input_steps, b_output_steps)) {
    report_failure("alternate B");
    return 0;
  }

  for (int32_t w = 1; w < num_warmups; w++) {
    write_insts(b.instr, *insts_a);
    set_config(b.config, a_input_steps, a_output_steps);
    issue_run(kernel, b, insts_a->size());

    write_insts(b.instr, *insts_b);
    set_config(b.config, b_input_steps, b_output_steps);
    issue_run(kernel, b, insts_b->size());
  }

  Stats s;
  for (int32_t i = 0; i < num_calls; i++) {
    const bool is_a = (i % 2 == 0);
    const std::vector<uint32_t>& insts = is_a ? *insts_a : *insts_b;
    int32_t input_steps = is_a ? a_input_steps : b_input_steps;
    int32_t output_steps = is_a ? a_output_steps : b_output_steps;

    auto t0 = std::chrono::steady_clock::now();
    write_insts(b.instr, insts);
    set_config(b.config, input_steps, output_steps);
    issue_run(kernel, b, insts.size());
    auto t1 = std::chrono::steady_clock::now();

    s.add(std::chrono::duration<double, std::micro>(t1 - t0).count());
  }
  s.report("alternate A/B", num_calls);
  return 0;
}

// Launch alternating workloads, with a reused xrt::run object for each.
static int mode_reuse(xrt::device& device,
                      xrt::kernel& kernel,
                      int32_t a_input_steps,
                      int32_t a_output_steps,
                      int32_t b_input_steps,
                      int32_t b_output_steps,
                      int32_t num_calls,
                      int32_t num_warmups) {
  RunCtx a = make_run(device, kernel, a_input_steps, a_output_steps);
  RunCtx b = make_run(device, kernel, b_input_steps, b_output_steps);

  // Verify the first warmup run.
  a.run.start();
  a.run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
  if (!verify(a.bos.outputs, a_input_steps, a_output_steps)) {
    report_failure("reuse A");
    return 0;
  }

  b.run.start();
  b.run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
  if (!verify(b.bos.outputs, b_input_steps, b_output_steps)) {
    report_failure("reuse B");
    return 0;
  }

  for (int32_t w = 1; w < num_warmups; w++) {
    a.run.start();
    a.run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
    b.run.start();
    b.run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
  }

  Stats s;
  for (int32_t i = 0; i < num_calls; i++) {
    xrt::run& run = (i % 2 == 0) ? a.run : b.run;
    s.add(timed_start(run));
  }
  s.report("reuse A/B", num_calls);
  return 0;
}

// Launch alternating workloads, starting the next xrt::run before waiting for
// the last.
static int mode_pipeline(xrt::device& device,
                         xrt::kernel& kernel,
                         int32_t a_input_steps,
                         int32_t a_output_steps,
                         int32_t b_input_steps,
                         int32_t b_output_steps,
                         int32_t num_calls,
                         int32_t num_warmups) {
  RunCtx a = make_run(device, kernel, a_input_steps, a_output_steps);
  RunCtx b = make_run(device, kernel, b_input_steps, b_output_steps);

  // Warm up both shapes (start + wait each num_warmups times) so cold-start
  // cost is not counted, matching the other modes. Verify the first warmup
  // run of each shape.
  a.run.start();
  a.run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
  if (!verify(a.bos.outputs, a_input_steps, a_output_steps)) {
    report_failure("pipeline A");
    return 0;
  }

  b.run.start();
  b.run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
  if (!verify(b.bos.outputs, b_input_steps, b_output_steps)) {
    report_failure("pipeline B");
    return 0;
  }

  for (int32_t w = 1; w < num_warmups; w++) {
    a.run.start();
    a.run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
    b.run.start();
    b.run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
  }

  auto startTime = std::chrono::steady_clock::now();
  a.run.start();
  b.run.start();
  for (int32_t i = 0; i < num_calls; i++) {
    xrt::run& run = (i % 2 == 0) ? a.run : b.run;
    run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
    run.start();
  }
  a.run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
  b.run.wait2(std::chrono::milliseconds(kRunTimeoutMs));
  auto endTime = std::chrono::steady_clock::now();

  double total =
      std::chrono::duration<double, std::micro>(endTime - startTime).count();
  printf("  %-20s %7.1f  (total %.1f us over %d calls)\n", "pipeline A/B",
         total / num_calls, total, num_calls);
  return 0;
}

int main(int argc, char** argv) {
  std::string mode = argc > 1 ? argv[1] : "alternate";
  int32_t num_calls = argc > 2 ? std::stoi(argv[2]) : 16;
  int32_t num_warmups = argc > 3 ? std::stoi(argv[3]) : 8;
  int32_t scale = argc > 4 ? std::stoi(argv[4]) : 1;

  // Steps for 2048 -> 4096 and 4096 -> 2048 sizes.
  const int32_t kAInputSteps = 32 * scale, kAOutputSteps = 2 * scale;
  const int32_t kBInputSteps = 64 * scale, kBOutputSteps = 1 * scale;

  auto device = xrt::device(0);
  auto xclbin = xrt::xclbin(std::string("aie.xclbin"));
  device.register_xclbin(xclbin);
  auto context = xrt::hw_context(device, xclbin.get_uuid(),
                                 xrt::hw_context::access_mode::exclusive);
  auto kernel = xrt::kernel(context, "MLIR_AIE");

  if (mode == "repeat-a")
    return mode_repeat(device, kernel, "repeat A", kAInputSteps, kAOutputSteps,
                       num_calls, num_warmups);
  if (mode == "repeat-b")
    return mode_repeat(device, kernel, "repeat B", kBInputSteps, kBOutputSteps,
                       num_calls, num_warmups);
  if (mode == "alternate")
    return mode_alternate(device, kernel, kAInputSteps, kAOutputSteps,
                          kBInputSteps, kBOutputSteps, num_calls, num_warmups);
  if (mode == "reuse")
    return mode_reuse(device, kernel, kAInputSteps, kAOutputSteps, kBInputSteps,
                      kBOutputSteps, num_calls, num_warmups);
  if (mode == "pipeline")
    return mode_pipeline(device, kernel, kAInputSteps, kAOutputSteps,
                         kBInputSteps, kBOutputSteps, num_calls, num_warmups);

  fprintf(stderr, "error: unrecognized mode: '%s'\n", mode.c_str());
  return 2;
}
